// Matthew's portfolio homepage.
// This renders the static portfolio design (self-contained HTML/CSS) that
// replaced the previous interactive site. Styles and markup are injected
// directly to avoid re-authoring the whole page as JSX.

const PAGE_CSS = `:root {
    --bg: #181818;
    --text-heading: #f7f7f5;
    --text-body: #c7c7c2;
    --text-muted: #8a8a83;
    --line: #7a7a73;
    --line-hover: #f7f7f5;
    --avatar-ring: #2a2a28;
    --sans: Georgia, Palatino, "Palatino Linotype", Times, "Times New Roman", serif;
  }

  * { box-sizing: border-box; }

  html, body {
    margin: 0;
    padding: 0;
    background: var(--bg);
    color: var(--text-body);
    font-family: var(--sans);
    -webkit-font-smoothing: antialiased;
    /* Hide the scrollbar at the document level (not on a nested container)
       so the page always scrolls natively — this is what actually works
       reliably across mobile browsers and in-app WebViews (Instagram,
       TikTok, etc.), which often can't touch-scroll a div nested inside
       an overflow:hidden parent. Hiding it here means no gutter is ever
       reserved, so horizontal centering never shifts when content grows. */
    scrollbar-width: none; /* Firefox */
    -ms-overflow-style: none; /* legacy Edge/IE */
  }
  html::-webkit-scrollbar, body::-webkit-scrollbar {
    display: none; /* Chrome, Safari, Edge (Chromium) */
    width: 0;
    height: 0;
  }

  /* min-height (not height) + flex centering: short content centers
     vertically, and anything taller than the viewport just grows the
     page and scrolls natively from the top — no custom scroll container. */
  body {
    min-height: 100vh;
    min-height: 100dvh;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  .page {
    max-width: 680px;
    width: 100%;
    padding: clamp(40px, 8vw, 72px) clamp(20px, 5vw, 24px) 96px;
    box-sizing: border-box;
  }

  h1 {
    font-size: 26px;
    font-weight: 800;
    letter-spacing: -0.01em;
    margin: 0 0 20px;
    line-height: 1.1;
    color: var(--text-heading);
  }

  h2 {
    font-size: 22px;
    font-weight: 700;
    letter-spacing: -0.005em;
    margin: 20px 0 18px;
    line-height: 1.1;
    color: var(--text-heading);
  }

  .intro {
    margin-bottom: 8px;
  }

  .avatar {
    width: clamp(110px, 15vw, 168px);
    height: clamp(110px, 15vw, 168px);
    border-radius: 50%;
    background: var(--avatar-ring);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
    color: var(--text-muted);
    text-align: center;
    line-height: 1.4;
    overflow: hidden;
    margin: 0 0 24px;
    position: relative;
  }
  .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: 50% 50%;
    display: block;
  }

  p {
    font-size: 17px;
    line-height: 1.4;
    color: var(--text-body);
    margin: 0 0 20px;
    text-wrap: pretty;
  }

  p strong { color: var(--text-heading); font-weight: 700; }

  a {
    color: var(--text-heading);
    text-decoration: underline;
    text-decoration-color: var(--line);
    text-underline-offset: 3px;
    font-weight: 500;
  }
  a:hover { text-decoration-color: var(--line-hover); }

  ul.dash-list {
    list-style: none;
    margin: 0;
    padding: 0;
  }
  ul.dash-list li {
    position: relative;
    padding-left: 22px;
    font-size: 17px;
    line-height: 1.3;
    color: var(--text-body);
    margin-bottom: 7px;
    text-wrap: pretty;
  }
  ul.dash-list li::before {
    content: "–";
    position: absolute;
    left: 0;
    top: 0;
    color: var(--text-muted);
  }
  ul.dash-list li a { color: var(--text-heading); }

  .media-group {
    margin: 0;
  }
  .media-group:last-of-type {
    margin-bottom: 20px;
  }
  .media-group summary {
    cursor: pointer;
    list-style: none;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 0;
    font-size: 17px;
    font-weight: 400;
    line-height: 1.4;
    color: var(--text-body);
    -webkit-tap-highlight-color: transparent;
  }
  .media-group summary::-webkit-details-marker { display: none; }
  .media-group summary::marker { content: ""; }
  .media-group summary .toggle-icon {
    position: relative;
    width: 12px;
    height: 12px;
    flex-shrink: 0;
  }
  .media-group summary .toggle-icon::before,
  .media-group summary .toggle-icon::after {
    content: "";
    position: absolute;
    background: var(--text-muted);
    transition: transform 0.2s ease, background-color 0.15s ease;
  }
  .media-group summary .toggle-icon::before {
    top: 50%;
    left: 0;
    width: 100%;
    height: 1.5px;
    transform: translateY(-50%);
  }
  .media-group summary .toggle-icon::after {
    left: 50%;
    top: 0;
    height: 100%;
    width: 1.5px;
    transform: translateX(-50%);
  }
  .media-group[open] summary .toggle-icon::after {
    transform: translateX(-50%) rotate(90deg);
  }
  .media-group summary:hover .toggle-icon::before,
  .media-group summary:hover .toggle-icon::after {
    background: var(--text-heading);
  }
  .media-group .media-content {
    padding: 8px 0 0 22px;
  }

  footer {
    margin-top: 44px;
    font-size: 14px;
    color: var(--text-muted);
  }

  @media (max-width: 900px) {
    .page { max-width: 92vw; }
  }

  @media (max-width: 640px) {
    h1 { font-size: 25px; }
    h2 { font-size: 19px; }
    p, ul.dash-list li { font-size: 15px; }
  }

  @media (max-width: 400px) {
    h1 { font-size: 22px; }
  }`;

